#include <iostream>
#include <vector>

class IntBuffer {
public:
    // Explicit constructor prevents implicit int -> IntBuffer conversion
    explicit IntBuffer(size_t capacity)
        : data_(capacity, 0) {}

    // Explicit conversion operator to bool (C++11/C++17)
    explicit operator bool() const noexcept {
        return !data_.empty();
    }

    size_t size() const noexcept {
        return data_.size();
    }

    int get(size_t index) const {
        return data_.at(index);
    }

private:
    std::vector<int> data_;
};

void inspectBuffer(const IntBuffer& buf) {
    std::cout << "Buffer valid: " << (buf ? "true" : "false")
              << ", size: " << buf.size() << "\n";
}

int main() {
    IntBuffer b1(5);
    inspectBuffer(b1);

    // inspectBuffer(3); // COMPILE ERROR: constructor is explicit!
    inspectBuffer(IntBuffer(3)); // OK: explicit instantiation

    // Explicit cast via static_cast or contextual bool evaluation in if
    if (b1) {
        std::cout << "Explicit bool conversion succeeded in if-condition\n";
    }
    bool flag = static_cast<bool>(b1); // OK: explicit cast
    std::cout << "Explicit static_cast<bool>: " << flag << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

// Demonstrating operator() for 2D matrix indexing
class Matrix2D {
public:
    Matrix2D(size_t rows, size_t cols)
        : rows_(rows), cols_(cols), data_(rows * cols, 0) {}

    // Overloaded () for non-const element access
    int& operator()(size_t row, size_t col) {
        return data_.at(row * cols_ + col);
    }

    // Overloaded () for const element access
    const int& operator()(size_t row, size_t col) const {
        return data_.at(row * cols_ + col);
    }

    size_t rows() const noexcept { return rows_; }
    size_t cols() const noexcept { return cols_; }

private:
    size_t rows_;
    size_t cols_;
    std::vector<int> data_;
};

// Demonstrating operator() for substring slice
class MyString {
public:
    MyString(std::string s) : text_(std::move(s)) {}

    // Substring selector: text(start, length)
    std::string operator()(size_t start, size_t length) const {
        if (start >= text_.size()) return "";
        return text_.substr(start, length);
    }

    const std::string& str() const noexcept { return text_; }

private:
    std::string text_;
};

int main() {
    Matrix2D mat(2, 3);
    mat(0, 1) = 42; // invokes non-const operator()(size_t, size_t)
    mat(1, 2) = 99;

    std::cout << "mat(0, 1) = " << mat(0, 1) << "\n";
    std::cout << "mat(1, 2) = " << mat(1, 2) << "\n";

    MyString s("AEIOU");
    std::string sub = s(2, 3); // invokes operator()(2, 3) -> "IOU"
    std::cout << "s(2, 3) = " << sub << "\n";

    return 0;
}
